import sys

def solve():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    P = list(map(int, data[1:1 + N]))

    pos = [0] * (N + 1)
    for i, x in enumerate(P, 1):
        pos[x] = i

    bit = [0] * (N + 1)

    def add(i, x):
        while i <= N:
            bit[i] += x
            i += i & -i

    def sum_prefix(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    for i in range(1, N + 1):
        add(i, 1)

    ans = 0
    for v in range(N, 0, -1):
        cur = sum_prefix(pos[v])
        if cur < v:
            d = v - cur
            ans += (cur + v - 1) * d // 2
        add(pos[v], -1)

    print(ans)

if __name__ == "__main__":
    solve()
